$ErrorActionPreference='Stop'
Add-Type -AssemblyName UIAutomationClient
Add-Type @"
using System;using System.Runtime.InteropServices;public class S360AuditAccept{[DllImport("user32.dll")]public static extern bool SetForegroundWindow(IntPtr hWnd);[DllImport("user32.dll")]public static extern bool SetCursorPos(int X,int Y);[DllImport("user32.dll")]public static extern void mouse_event(uint flags,uint dx,uint dy,uint data,UIntPtr extra);}
"@
$root=[System.Windows.Automation.AutomationElement]::RootElement;$wins=$root.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);$w=$wins|Where-Object {$_.Current.Name -like '*Society360*Google Chrome'}|Select-Object -First 1;if(!$w){throw 'Society360 Chrome window missing'};$null=[S360AuditAccept]::SetForegroundWindow([IntPtr]$w.Current.NativeWindowHandle);[S360AuditAccept]::SetCursorPos(150,640)|Out-Null;for($i=0;$i -lt 5;$i++){[S360AuditAccept]::mouse_event(0x0800,0,0,[uint32]4294967176,[UIntPtr]::Zero);Start-Sleep -Milliseconds 120};Start-Sleep -Milliseconds 300
$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$trail=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq 'Audit Trail'}|Select-Object -First 1
if(!$trail){$parent=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq 'Audit & Governance' -and -not $_.Current.IsOffscreen}|Select-Object -First 1;if(!$parent){throw 'Audit & Governance navigation parent not found after scrolling'};$r=$parent.Current.BoundingRectangle;[S360AuditAccept]::SetCursorPos([int]($r.X+$r.Width/2),[int]($r.Y+$r.Height/2))|Out-Null;[S360AuditAccept]::mouse_event(2,0,0,0,[UIntPtr]::Zero);[S360AuditAccept]::mouse_event(4,0,0,0,[UIntPtr]::Zero);Start-Sleep -Milliseconds 500;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$trail=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq 'Audit Trail'}|Select-Object -First 1}
for($i=0;$i -lt 5 -and $trail -and $trail.Current.IsOffscreen;$i++){[S360AuditAccept]::SetCursorPos(150,640)|Out-Null;[S360AuditAccept]::mouse_event(0x0800,0,0,[uint32]4294967176,[UIntPtr]::Zero);Start-Sleep -Milliseconds 150;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$trail=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Button -and $_.Current.Name -eq 'Audit Trail'}|Select-Object -First 1}
if(!$trail -or $trail.Current.IsOffscreen){throw 'Audit Trail submenu could not be made visible'};$r=$trail.Current.BoundingRectangle;[S360AuditAccept]::SetCursorPos([int]($r.X+$r.Width/2),[int]($r.Y+$r.Height/2))|Out-Null;[S360AuditAccept]::mouse_event(2,0,0,0,[UIntPtr]::Zero);[S360AuditAccept]::mouse_event(4,0,0,0,[UIntPtr]::Zero);Start-Sleep -Seconds 2
$root=[System.Windows.Automation.AutomationElement]::RootElement;$wins=$root.FindAll([System.Windows.Automation.TreeScope]::Children,[System.Windows.Automation.Condition]::TrueCondition);$w=$wins|Where-Object {$_.Current.Name -like '*Society360*Google Chrome'}|Select-Object -First 1;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$items=@($all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::DataItem -and $_.Current.Name -match '^\d{1,2}/\d{1,2}/\d{2},'});$headers=@($all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::DataItem -and $_.Current.Name -match 'Time User Login name Entity Record Action Old Values New Values'});$sensitive=@($items|Where-Object {$_.Current.Name -match 'password_hash|last_login_session_id|access_token|api_key'});Write-Output 'AUDIT_UI=OPEN';Write-Output ('AUDIT_ROWS_VISIBLE='+$items.Count);Write-Output ('AUDIT_HEADERS='+$headers.Count);Write-Output ('SENSITIVE_FIELDS_VISIBLE='+$sensitive.Count)
$search=$all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::Edit -and $_.Current.Name -eq 'Search user / action / entity'}|Select-Object -First 1;if(!$search){throw 'Audit search input missing'};$vp=$search.GetCurrentPattern([System.Windows.Automation.ValuePattern]::Pattern);$vp.SetValue('t_receipt');Start-Sleep -Milliseconds 700;$all=$w.FindAll([System.Windows.Automation.TreeScope]::Descendants,[System.Windows.Automation.Condition]::TrueCondition);$filtered=@($all|Where-Object {$_.Current.ControlType -eq [System.Windows.Automation.ControlType]::DataItem -and $_.Current.Name -match '^\d{1,2}/\d{1,2}/\d{2},'});Write-Output ('FILTERED_ROWS_VISIBLE='+$filtered.Count);if($filtered.Count -lt 1){throw 'Audit search did not return matching receipt audit rows'};$vp.SetValue('');Start-Sleep -Milliseconds 300
